from fastapi import FastAPI, Depends, Query
from pydantic import BaseModel, Field, ConfigDict
from fastapi.testclient import TestClient

app = FastAPI()

class MyModel(BaseModel):
    model_config = ConfigDict(populate_by_name=False)
    q: str = Field(
        default=Query(), 
        alias="query_param"
    )

@app.get("/")
def read_root(params: MyModel = Depends()):
    return params

client = TestClient(app)

def test_alias_extraction():
    response = client.get("/?query_param=hello")
    print(f"Alias extraction response: {response.json()}")
    assert response.status_code == 200, f"Expected 200, got {response.status_code}. Response: {response.json()}"
    assert response.json() == {"q": "hello"}

def test_name_extraction_error():
    response = client.get("/?q=hello")
    print(f"Name extraction response: {response.json()}")
    assert response.status_code == 422
    detail = response.json()["detail"]

    found_q_in_input = False
    for error in detail:
        if error.get("input") and "q" in error["input"]:
            found_q_in_input = True
            break

    assert found_q_in_input, f"Expected 'q' to be in the input of the error, but it wasn't. Response: {response.json()}"

if __name__ == "__main__":
    try:
        test_alias_extraction()
        print("test_alias_extraction passed")
    except Exception as e:
        print(f"test_alias_extraction failed: {e}")

    try:
        test_name_extraction_error()
        print("test_name_extraction_error passed")
    except Exception as e:
        print(f"test_name_extraction_error failed: {e}")
